<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {api} from '@/api/client'
import type {Account} from '@/auth/session'
const accounts=ref<Account[]>([]),busy=ref(false),error=ref(''),message=ref(''),name=ref(''),password=ref(''),resetFor=ref<string|null>(null),resetValue=ref(''),adminOnly=ref(true)
async function refresh(){const data=await api<{accounts:Account[];admin_only:boolean}>('/api/admin/accounts');accounts.value=data.accounts;adminOnly.value=data.admin_only}
async function act(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
function create(){void act(async()=>{await api('/api/admin/accounts',{body:{username:name.value,password:password.value}});name.value=password.value='';message.value='独立账号已创建，默认停用，当前仍仅管理员可登录。';await refresh()})}
function enable(a:Account){void act(async()=>{await api('/api/admin/accounts/'+a.id,{method:'PATCH',body:{enabled:!a.enabled}});await refresh()})}
function reset(){void act(async()=>{await api('/api/admin/accounts/'+resetFor.value+'/password',{body:{new_password:resetValue.value}});resetValue.value='';resetFor.value=null;message.value='密码已重设，原登录会话已撤销。'})}
onMounted(()=>void act(refresh))
</script>
<template><main class="accounts-page"><header><router-link to="/?home=1" aria-label="Firework · 返回首页">Firework · 首页</router-link><span>Firework · 管理员</span></header><p class="eyebrow">ACCOUNT MANAGEMENT</p><h1>账号管理</h1><p class="muted">账号之间的论文、文件、会话、技能与检索空间独立。管理员在此管理账号状态，不读取其他账号的研究资料。</p><div class="account-policy">公开注册关闭 · {{adminOnly?'仅当前管理员可以登录':'已允许启用的账号登录'}}</div><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="message" role="status">{{message}}</p><section><h2>创建独立账号</h2><form @submit.prevent="create"><label>账号<input v-model="name" autocomplete="off" required minlength="3" maxlength="80" placeholder="3–80 位字母、数字或 _ . @ -"></label><label>初始密码<input v-model="password" type="password" autocomplete="new-password" required minlength="12" maxlength="256"></label><button class="primary" :disabled="busy">创建（默认停用）</button></form></section><section><h2>账号列表</h2><div class="account-table"><table><thead><tr><th>账号</th><th>角色</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="a in accounts" :key="a.id"><td>{{a.username}}</td><td>{{a.role==='admin'?'管理员':'普通账号'}}</td><td>{{a.login_allowed?'可登录':a.enabled?'发布限制中':'已停用'}}</td><td><template v-if="a.role!=='admin'"><button :disabled="busy" @click="enable(a)">{{a.enabled?'停用':'启用账号'}}</button><button :disabled="busy" @click="resetFor=a.id;resetValue=''">重设密码</button></template><span v-else>受保护的当前管理员</span></td></tr></tbody></table></div><p class="muted">当前发布限制独立于账号启停；启用普通账号也不会放开管理员专用阶段的登录限制。</p></section><section v-if="resetFor"><h2>重设账号密码</h2><form @submit.prevent="reset"><label>新密码<input v-model="resetValue" type="password" autocomplete="new-password" minlength="12" maxlength="256" required></label><button class="primary" :disabled="busy">确认重设并撤销旧会话</button><button type="button" @click="resetFor=null;resetValue=''">取消</button></form></section></main></template>
<style scoped>.accounts-page{max-width:1000px;margin:auto;padding:28px;color:var(--text)}header{display:flex;justify-content:space-between;font-size:13px;margin-bottom:40px}h1{font-size:28px}h2{font-size:17px}section{margin:24px 0;padding:22px;border:1px solid var(--border);border-radius:10px;background:var(--bg)}.muted{font-size:13px;line-height:1.8}.account-policy{padding:12px;background:var(--accent-soft);border-radius:7px}form{display:flex;flex-wrap:wrap;gap:14px;align-items:end}label{display:grid;gap:7px;font-size:12px}input{padding:10px;min-width:240px}.account-table{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}td,th{text-align:left;border-bottom:1px solid var(--border);padding:14px 8px}td button{margin-right:8px}.error{color:var(--danger)}a{color:var(--accent)}</style>
